)values
( #{TStdMeteModelDetail.deviceMeteId, jdbcType=BIGINT}, #{deviceId, jdbcType=BIGINT}, ifnull(#{TStdMeteModelDetail.devicePointId, jdbcType=VARCHAR},"00"), #{TStdMeteModelDetail.customType, jdbcType=VARCHAR}, #{TStdMeteModelDetail.customName, jdbcType=VARCHAR}, #{TStdMeteModelDetail.meteId, jdbcType=BIGINT}, #{TStdMeteModelDetail.meteKind, jdbcType=INTEGER}, #{TStdMeteModelDetail.meteType, jdbcType=VARCHAR}, #{TStdMeteModelDetail.meterType, jdbcType=INTEGER}, #{TStdMeteModelDetail.meteName, jdbcType=VARCHAR}, #{TStdMeteModelDetail.appearanceType, jdbcType=INTEGER}, #{TStdMeteModelDetail.deviceType, jdbcType=INTEGER}, ifnull(#{TStdMeteModelDetail.inspectionType, jdbcType=INTEGER},1), #{TStdMeteModelDetail.positionType, jdbcType=VARCHAR}, #{TStdMeteModelDetail.analyseType, jdbcType=INTEGER}, #{TStdMeteModelDetail.isAi, jdbcType=VARCHAR}, #{TStdMeteModelDetail.isJudge,jdbcType=VARCHAR}, #{TStdMeteModelDetail.unit, jdbcType=VARCHAR}, #{TStdMeteModelDetail.alarmNote, jdbcType=VARCHAR}, #{TStdMeteModelDetail.alarmType, jdbcType=VARCHAR}, #{TStdMeteModelDetail.upEffect, jdbcType=REAL}, #{TStdMeteModelDetail.downEffect, jdbcType=REAL}, #{TStdMeteModelDetail.alarmLevel, jdbcType=INTEGER}, #{TStdMeteModelDetail.highLimit1, jdbcType=REAL}, #{TStdMeteModelDetail.lowLimit1, jdbcType=REAL}, #{TStdMeteModelDetail.highLimit2, jdbcType=REAL}, #{TStdMeteModelDetail.lowLimit2, jdbcType=REAL}, #{TStdMeteModelDetail.highLimit3, jdbcType=REAL}, #{TStdMeteModelDetail.lowLimit3, jdbcType=REAL}, #{TStdMeteModelDetail.highLimit4, jdbcType=REAL}, #{TStdMeteModelDetail.lowLimit4, jdbcType=REAL}, #{TStdMeteModelDetail.alarmDelay, jdbcType=INTEGER}, #{TStdMeteModelDetail.alarmCnt, jdbcType=INTEGER}, #{TStdMeteModelDetail.thresholdAbs, jdbcType=NUMERIC}, #{TStdMeteModelDetail.thresholdPer, jdbcType=NUMERIC}, #{TStdMeteModelDetail.modulus, jdbcType=INTEGER}, #{TStdMeteModelDetail.remark, jdbcType=VARCHAR}, #{TStdMeteModelDetail.stateZero, jdbcType=VARCHAR}, #{TStdMeteModelDetail.stateOne, jdbcType=VARCHAR}, #{TStdMeteModelDetail.isTemdif, jdbcType=INTEGER}, ifnull(#{TStdMeteModelDetail.alarmState, jdbcType=INTEGER},"1"), #{TStdMeteModelDetail.redundantType, jdbcType=VARCHAR}
)

mapper.select:
select DISTINCT
a.device_mete_id,
a.device_id,
a.device_point_id,
a.custom_id as customType,
a.mete_id,
a.mete_kind,
a.meter_type,
a.mete_name,
a.appearance_type,
a.device_type,
a.inspection_type,
a.position_type,
a.analyse_type,
a.is_ai,
a.unit,
a.alarm_note,
a.alarm_type,
a.up_effect,
a.down_effect,
a.alarm_level,
a.high_limit1,
a.low_limit1,
a.high_limit2,
a.low_limit2,
a.high_limit3,
a.low_limit3,
a.high_limit4,
a.low_limit4,
a.alarm_delay,
a.alarm_cnt,
a.threshold_abs,
a.threshold_per,
a.mete_type,
a.modulus,
a.remark,
state_zero,
state_one,
alarm_state,
a.redundant_type,
g.dict_note as alarmLevelName,
f.dict_note as alarmTypeName,
i.dict_note as customTypeName,
b.dict_note as meteTypeName,
d.dict_note as meteKindName,
e.device_name as deviceName,
e.up_region_id,
h.dict_note as unitName,
a.analyse_type,
a.is_temdif,
l.dict_note as analyseTypeName
from t_std_devicemete a
left join  t_dict_business g on a.alarm_level= g.dict_code
left join t_dict_business f on a.alarm_type= f.dict_code
left join t_dict_business b on a.mete_type= b.dict_code
left join t_dict_business d on a.mete_kind= d.dict_code and d.col_name="mete_kind"
left join t_std_device e on a.device_id = e.device_id
left join t_dict_business h on a.unit = h.dict_code
left join t_dict_business i on a.custom_id = i.dict_code
left join t_dict_business l on a.analyse_type = l.dict_code and (l.col_name="analyse_type" or l.col_name="defect_type" )
where 1=1
 and a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.device_point_id = #{devicePointId, jdbcType=VARCHAR}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.mete_id = #{meteId, jdbcType=BIGINT}
 and a.mete_kind = #{meteKind, jdbcType=VARCHAR}
 and a.meter_type = #{meterType, jdbcType=INTEGER}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.appearance_type = #{appearanceType, jdbcType=INTEGER}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.inspection_type = #{inspectionType, jdbcType=VARCHAR}
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.device_type = #{analyseType, jdbcType=INTEGER}
 and a.unit = #{unit, jdbcType=VARCHAR}
 and a.alarm_note = #{alarmNote, jdbcType=VARCHAR}
 and a.alarm_type = #{alarmType, jdbcType=VARCHAR}
 and a.up_effect = #{upEffect, jdbcType=REAL}
 and a.down_effect = #{downEffect, jdbcType=REAL}
 and a.alarm_level = #{alarmLevel, jdbcType=INTEGER}
 and a.high_limit1 = #{highLimit1, jdbcType=REAL}
 and a.low_limit1 = #{lowLimit1, jdbcType=REAL}
 and a.high_limit2 = #{highLimit2, jdbcType=REAL}
 and a.low_limit2 = #{lowLimit2, jdbcType=REAL}
 and a.alarm_delay = #{alarmDelay, jdbcType=INTEGER}
 and a.alarm_cnt = #{alarmCnt, jdbcType=INTEGER}
 and a.threshold_abs = #{thresholdAbs, jdbcType=NUMERIC}
 and a.threshold_per = #{thresholdPer, jdbcType=NUMERIC}
 and a.mete_type = #{meteType, jdbcType=VARCHAR}
 and a.modulus = #{modulus, jdbcType=INTEGER}
 and a.is_temdif = #{isTemdif, jdbcType=INTEGER}
 and a.remark = #{remark, jdbcType=VARCHAR}
a.state_zero = #{stateZero, jdbcType=VARCHAR}
a.state_one = #{stateOne, jdbcType=VARCHAR}
a.alarm_state = #{alarmState, jdbcType=INTEGER}
 and g.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%')

SELECT DISTINCT b.device_mete_id AS "deviceMeteId", b.device_id AS "deviceId", b.mete_name AS "meteName" FROM ( ( t_std_device a JOIN t_std_devicemete b ON a.device_id = b.device_id ) JOIN t_cruise_point_instance c ON b.device_mete_id = c.device_mete_id ) JOIN ( t_cruise_task_result_detail d LEFT JOIN t_cruise_data_result e ON d.cruise_result_id = e.cruise_result_id ) ON c.instance_id = d.instance_id LEFT JOIN t_cruise_result f ON d.task_result_id = f.task_result_id LEFT JOIN t_dict_business g ON f.c_state = g.dict_code AND g.col_name = 'task_state' WHERE b.device_id IN
#{deviceIds,jdbcType=BIGINT}
AND f.c_state != 239 AND f.c_state != 241 ORDER BY d.end_time, d.device_id, b.device_mete_id DESC

SELECT DISTINCT f.device_mete_id, f.device_id, f.device_point_id, f.mete_type, f.meter_type, g.device_type, f.mete_name, b.cruise_time FROM t_cruise_result a, t_cruise_task_result_detail b, t_cruise_data_result d, t_cruise_point_instance e, t_std_devicemete f, t_std_device g where a.task_result_id = b.task_result_id and a.c_state != 239 and a.c_state != 241 and d.cruise_result_id = b.cruise_result_id and e.instance_id = b.instance_id and f.device_mete_id = e.device_mete_id and g.device_id = f.device_id and a.device_type = #{deviceType,jdbcType = INTEGER} and b.meter_type = #{meterType,jdbcType = INTEGER} and b.mete_type = #{meteType,jdbcType = INTEGER} and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
GROUP BY device_mete_id ORDER BY cruise_time desc

SELECT b.instance_id, f.device_mete_id, f.device_id, f.device_point_id, f.mete_type, f.meter_type, g.device_type, f.mete_name, h.update_time as cruise_time, h.pic_Path, h.cruise_result, IFNULL(h.identify_result, h.cruise_result) as FinalState, k.dict_note as cruise_result_name, h.identify_result FROM u_patrol_data_result b LEFT JOIN t_cruise_point_instance e on e.instance_id = b.instance_id JOIN t_std_devicemete f on f.device_mete_id = e.device_mete_id LEFT JOIN t_std_device g on g.device_id = f.device_id LEFT JOIN t_std_devicemete_update h on h.device_mete_id = e.device_mete_id LEFT JOIN t_dict_business k on k.dict_code = h.cruise_result and k.col_name = 'cruise_result' where 1 = 1 and g.device_type = #{deviceType,jdbcType = INTEGER} and f.meter_type = #{meterType,jdbcType = INTEGER} and f.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%') and f.mete_type = #{meteType,jdbcType = INTEGER}
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
and e.custom_id = #{customId,jdbcType = BIGINT} and IFNULL(h.identify_result, h.cruise_result) IN (246,261) GROUP BY f.device_mete_id ORDER BY cruise_time desc

SELECT b.instance_id, f.device_mete_id, f.device_id, f.device_point_id, f.mete_type, f.meter_type, g.device_type, f.mete_name, h.update_time as cruise_time, h.pic_Path, h.cruise_result, IFNULL(h.identify_result, h.cruise_result) as FinalState, k.dict_note as cruise_result_name, h.identify_result FROM u_patrol_data_result b LEFT JOIN t_cruise_point_instance e on e.instance_id = b.instance_id JOIN t_std_devicemete f on f.device_mete_id = e.device_mete_id LEFT JOIN t_std_device g on g.device_id = f.device_id LEFT JOIN t_std_devicemete_update h on h.device_mete_id = e.device_mete_id LEFT JOIN t_dict_business k on k.dict_code = h.cruise_result and k.col_name = 'cruise_result' where 1 = 1 and g.device_type = #{deviceType,jdbcType = INTEGER} and f.meter_type = #{meterType,jdbcType = INTEGER} and f.mete_name like concat('%',#{meteName, jdbcType=VARCHAR},'%') and f.mete_type = #{meteType,jdbcType = INTEGER}
and b.device_id IN
#{deviceIds,jdbcType=BIGINT}
and e.custom_id = #{customId,jdbcType = BIGINT} and IFNULL(h.identify_result, h.cruise_result) IN (247,262,263,264) GROUP BY f.device_mete_id ORDER BY cruise_time desc

select a.device_mete_id
from t_std_devicemete a
where a.device_id = #{deviceId,jdbcType=BIGINT}

select a.instance_id
from t_cruise_point_instance a
where a.device_mete_id = #{deviceMeteId, jdbcType=BIGINT}

select a.instance_id
from t_cruise_point_instance a
where a.device_id = #{deviceId,jdbcType=BIGINT}
